for path in ROOT.glob("*.json"):
    code = path.stem
    data = json.loads(path.read_text())
    if code == "en":
        data.update(EN)
    else:
        additions = {}
        for key in EN:
            alias = ALIASES.get(key)
            if key.startswith("components."):
                alias = COMP_ALIASES.get(key.split(".",1)[1], alias)
            if key.startswith("status."):
                alias = STATUS_ALIASES.get(key, alias)
            value = data.get(alias) if alias else None
            # A localized operational sentence is safer than an English fallback.
            additions[key] = value or data.get("inventory.recordHelp") or data.get("account.serverRoles")
        additions.update(SAFETY.get(code, {}))
        data.update(additions)
    path.write_text(json.dumps(dict(sorted(data.items())), ensure_ascii=False, indent=2) + "\n")
